raw_text:
{
  "narratives": [
    {
      "item_code": "S5_MEDIA",
      "title_raw": "가. 적절한(부적절한) 소화제",
      "start": "p3:L13",
      "end": "p3:L20"
    },
    {
      "item_code": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "start": "p3:L21",
      "end": "p3:L32"
    },
    {
      "item_code": "S5_FIREFIGHT",
      "title_raw": "다. 화재진압시 착용할 보호구 및 예방조치",
      "start": "p4:L2",
      "end": "p4:L15"
    }
  ],
  "extras": [
    {
      "after_item": "S5_MEDIA",
      "title_raw": "○ 적절한 소화제",
      "statements": [
        {
          "key": "적절한 소화제",
          "value": "CO2"
        ,
        "line": "p3:L15"
        },
        {
          "key": "적절한 소화제",
          "value": "건조화학제"
        ,
        "line": "p3:L16"
        },
        {
          "key": "적절한 소화제",
          "value": "이 물질과 관련된 소화시 알콜 포말, 이산화탄소 또는 물분무를 사용할 것."
        ,
        "line": "p3:L17"
        },
        {
          "key": "적절한 소화제",
          "value": "질식소화시 건조한 모래 또는 흙을 사용할 것."
        ,
        "line": "p3:L18"
        }
      ],
      "line": "p3:L14"
    },
    {
      "after_item": "S5_MEDIA",
      "title_raw": "○ 부적절한 소화제",
      "statements": [
        {
          "key": "부적절한 소화제",
          "value": "자료없음"
        ,
        "line": "p3:L20"
        }
      ],
      "line": "p3:L19"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 열분해성 생성물",
      "statements": [
        {
          "key": "열분해성 생성물",
          "value": "자료없음"
        ,
        "line": "p3:L23"
        }
      ],
      "line": "p3:L22"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 화재 및 폭발 위험",
      "statements": [
        {
          "key": "화재 및 폭발 위험",
          "value": "가열시 용기가 폭발할 수 있음."
        ,
        "line": "p3:L25"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "가열시 증기는 공기와 혼합하여 폭발성 혼합물을 형성할 수 있음; 실내, 실외, 하수구에 폭발 위험."
        ,
        "line": "p3:L26"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "격렬하게 중합반응하여 화재와 폭발을 일으킬 수 있음."
        ,
        "line": "p3:L27"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "공기와 폭발성 혼합물을 형성함."
        ,
        "line": "p3:L28"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "극인화성."
        ,
        "line": "p3:L29"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "수소(UN No. 1049)/중수소(UN No. 1957)/압축수소메탄혼합물(UN No. 2034)는 화염이 눈에 보이지 않음."
        ,
        "line": "p3:L30"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "열, 스파크, 화염에 의해 쉽게 점화함."
        ,
        "line": "p3:L31"
        },
        {
          "key": "화재 및 폭발 위험",
          "value": "화재에 노출된 실린더는 가연성 가스를 방출할 수 있음."
        ,
        "line": "p3:L32"
        }
      ],
      "line": "p3:L24"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 기타",
      "statements": [
        {
          "key": "기타",
          "value": "일부 물질은 고농도로 흡입시 자극적일 수 있음."
        ,
        "line": "p3:L34"
        },
        {
          "key": "기타",
          "value": "화재시 자극성, 부식성, 독성 가스를 발생할 수 있음."
        ,
        "line": "p3:L35"
        },
        {
          "key": "기타",
          "value": "화재에 노출된 실린더는 가연성 가스를 방출할 수 있음."
        ,
        "line": "p3:L36"
        }
      ],
      "line": "p3:L33"
    },
    {
      "after_item": "S5_FIREFIGHT",
      "title_raw": "다. 화재진압시 착용할 보호구 및 예방조치",
      "statements": [
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "누출이 중지되지 않는다면 누출가스화재를 소화하지 마시오."
        ,
        "line": "p4:L3"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "액화가스 증기는 공기보다 무겁기 때문에 지면을 따라 확산하니 주의하시오."
        ,
        "line": "p4:L4"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "위험하지 않다면 화재지역에서 용기를 옮기시오."
        ,
        "line": "p4:L5"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "지역을 벗어나 안전거리를 유지하여 소화하시오."
        ,
        "line": "p4:L6"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "탱크 화재시 결빙될 수 있으므로 노출원 또는 안전장치에 직접주수하지 마시오."
        ,
        "line": "p4:L7"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "탱크 화재시 대규모 화재의 경우 무인 소화장비를 이용하고 불가능하다면 물러나 타게 놔두시오."
        ,
        "line": "p4:L8"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "탱크 화재시 소화가 진화된 후에도 다량의 물로 용기를 식히시오."
        ,
        "line": "p4:L9"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "탱크 화재시 압력 방출장치에서 고음이 있거나 탱크가 변색할 경우 즉시 물러나시오."
        ,
        "line": "p4:L10"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "탱크 화재시 최대거리에서 소화하거나 무인 소화장비를 이용하시오."
        ,
        "line": "p4:L11"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "탱크 화재시 화염에 휩싸인 탱크에서 물러나시오."
        ,
        "line": "p4:L12"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "파손된 실린더는 날아오를 수 있으니 주의하시오."
        ,
        "line": "p4:L13"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "파손된 실린더는 전문가에 의해서만 취급하게 하시오."
        ,
        "line": "p4:L14"
        },
        {
          "key": "화재진압시 착용할 보호구 및 예방조치",
          "value": "화재 유형에 맞는 소화제를 사용하시오."
        ,
        "line": "p4:L15"
        }
      ],
      "line": "p4:L2"
    }
  ]
}

